def transform(grid):
    out = [row[:] for row in grid]
    bottom = grid[-1]
    # Contiguous nonzero runs along the bottom are the exemplar motifs.
    motifs = []
    c = 0
    while c < len(bottom):
        if bottom[c] == 0:
            c += 1
            continue
        start = c
        while c < len(bottom) and bottom[c] != 0:
            c += 1
        motifs.append(bottom[start:c])
    for r, row in enumerate(grid[:-1]):
        for c, value in enumerate(row):
            if value == 0:
                continue
            motif = next((m for m in motifs if value in m), None)
            if motif is None:
                continue
            start = c - motif.index(value) - (1 if len(motif) == 6 else 0)
            for j in range(max(0, start), min(len(row), start + len(motif))):
                out[r][j] = motif[j - start]
    return out", "exit_code": 0, "error": null}
